export interface KeyEvent {
  /** A platform-independent key name (e.g. "Enter", "a", "ctrl+c") OR text to type. */
  key: string;
  isText: boolean;
  action: KeyAction;
}

export interface ScrollEvent {
  x: number;
  y: number;
  deltaX: number;
  deltaY: number;
}

